function Maze2DUtils.Remap( t1, t2, s1, s2, x ) 
    return ((x - t1) / (t2 - t1) * (s2 - s1) + s1)
end 



function Maze2DUtils.DoShake( params_ )

    assert( not isNull( params_.transform ) )
    assert( params_.totalTime > 0 ) -- 0.4
    assert( params_.totalAmplitude > 0 ) -- 0.35 
    assert( params_.sinFreq > 0 ) -- 55.0
    assert( params_.peak > 0 and params_.peak < 1.0 ) -- 0.3 -- 峰值位置
    params_.shakeDir = (isNull(params_.shakeDir) and Vector3.right or params_.shakeDir )

    ---
    local time = 0
    local amplitude = 1
    local initPos = params_.transform.position

    while time < params_.totalTime do
    
        local t = time / params_.totalTime
        amplitude = ( t <= params_.peak ) and Maze2DUtils.Remap( 0, params_.peak, 0, params_.totalAmplitude, t ) or
        Maze2DUtils.Remap( params_.peak, 1, params_.totalAmplitude, 0, t )
        
        params_.transform.position = initPos + params_.shakeDir * Mathf.Sin(params_.sinFreq * time) * amplitude
        ---
        time = time + Time.deltaTime
        coroutine.yield(Yielders.EndOfFrame)
    end
    params_.transform.position = initPos
end




return Maze2DUtils